var a=`0729-daraba`;var n=`world-0729`;var i=`TD`;var o=`central-africa`;var r=4;var s=59;var l={en:`Daraba`,ua:`Дараба`};var g={en:`Daraba is a Chad classic prepared with yellow onion, tomato, okra, eggplant. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Дараба, страва кухні країни Чад зі складниками: жовта цибуля, помідор, бамія, баклажан. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,190,`g`],[`red-palm-oil`,50,`ml`],[`tomato`,290,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 38 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 38 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:38,i:[[`okra`,380,`g`],[`eggplant`,280,`g`],[`sweet-potato`,330,`g`],[`water`,760,`ml`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 10 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 10 хвилин до м’якості та готовності.`,t:[`simmering`],m:10,i:[[`peanut-butter`,130,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:a,id:n,country:`TD`,region:o,servings:4,minutes:59,title:l,text:g,steps:d};export{i as country,u as default,n as id,s as minutes,o as region,r as servings,a as slug,d as steps,g as text,l as title};